/** Arguments for `convert editor-to-global`. */
export interface ConvertEditorToGlobalParams {
    /** Editor-local tick position to convert. */
    editorTick: number;
}

/** Success payload of `convert editor-to-global`. */
export interface ConvertEditorToGlobalResult {
    /** Global project tick equivalent of the editor-local input tick. */
    globalTick: number;
}

/** Arguments for `convert global-to-editor`. */
export interface ConvertGlobalToEditorParams {
    /** Global project tick position to convert. */
    globalTick: number;
}

/** Success payload of `convert global-to-editor`. */
export interface ConvertGlobalToEditorResult {
    /** Editor-local tick equivalent of the global input tick. */
    editorTick: number;
}

/** Arguments for `convert measure-to-tick`. */
export interface ConvertMeasureToTickParams {
    /** Bar/measure number (0-based, must be \>= 0). */
    barPos: number;
    /** Beat position within the bar (0-based). Required when `--consider-beat-mode` is true. */
    beatPos?: number | null;
    /** When true, use beat-level precision; `--beat-pos` is then required. */
    considerBeatMode: boolean;
    /** Tick offset within the bar (beat mode off) or within the beat (beat mode on). Must be \>= 0. */
    tickOffset: number;
}

/** Success payload of `convert measure-to-tick`. */
export interface ConvertMeasureToTickResult {
    /** Corresponding project tick position, accounting for time-signature changes. */
    tick: number;
}

/** Arguments for `convert tick-to-measure`. */
export interface ConvertTickToMeasureParams {
    /** When true, return bar + beat + tickOffset; when false, return bar + tickOffset only. */
    considerBeatMode: boolean;
    /** Project tick position to convert (must be \>= 0). */
    tick: number;
}

/** Success payload of `convert tick-to-measure`. */
export interface ConvertTickToMeasureResult {
    /** Bar/measure number (0-based). */
    barPos: number;
    /** Beat position within the bar (0-based). Present only when considerBeatMode is true. */
    beatPos?: number;
    /** Tick offset within the bar (bar mode) or within the beat (beat mode). */
    tickOffset: number;
}

/** Arguments for `convert tick-to-time`. */
export interface ConvertTickToTimeParams {
    /** Project tick position to convert (must be \>= 0). */
    tick: number;
}

/** Success payload of `convert tick-to-time`. */
export interface ConvertTickToTimeResult {
    /** Corresponding position in seconds, accounting for tempo automation. */
    time: number;
}

/** Arguments for `convert time-to-tick`. */
export interface ConvertTimeToTickParams {
    /** Time in seconds to convert (must be \>= 0.0). */
    time: number;
}

/** Success payload of `convert time-to-tick`. */
export interface ConvertTimeToTickResult {
    /** Corresponding project tick position, accounting for tempo automation. */
    tick: number;
}

/** The `convert` operations, mirroring the canonical operation tree 1:1. */
export interface ConvertOperations {
    /**
     * Convert an editor-local tick to a global project tick (adds clip offset). Requires an active pattern editor.
     *
     * Ungated: a pure function, callable without any capability.
     */
    editorToGlobal(params: ConvertEditorToGlobalParams, options?: CallOptions): Promise<ConvertEditorToGlobalResult>;

    /**
     * Convert a global project tick to an editor-local tick (subtracts clip offset). Requires an active pattern editor.
     *
     * Ungated: a pure function, callable without any capability.
     */
    globalToEditor(params: ConvertGlobalToEditorParams, options?: CallOptions): Promise<ConvertGlobalToEditorResult>;

    /**
     * Convert a measure/beat position to project ticks, accounting for time-signature changes.
     *
     * Ungated: a pure function, callable without any capability.
     */
    measureToTick(params: ConvertMeasureToTickParams, options?: CallOptions): Promise<ConvertMeasureToTickResult>;

    /**
     * Convert ticks to a musical measure/beat position, accounting for time-signature changes.
     *
     * Ungated: a pure function, callable without any capability.
     */
    tickToMeasure(params: ConvertTickToMeasureParams, options?: CallOptions): Promise<ConvertTickToMeasureResult>;

    /**
     * Convert a tick position to seconds, accounting for tempo automation.
     *
     * Ungated: a pure function, callable without any capability.
     */
    tickToTime(params: ConvertTickToTimeParams, options?: CallOptions): Promise<ConvertTickToTimeResult>;

    /**
     * Convert a time position (seconds) to project ticks, accounting for tempo automation.
     *
     * Ungated: a pure function, callable without any capability.
     */
    timeToTick(params: ConvertTimeToTickParams, options?: CallOptions): Promise<ConvertTimeToTickResult>;
}

// --- device ----------------------------------------------------------------

/** Success payload of `device current`. */
export interface DeviceCurrentResult {
    /** Active audio device type/backend (e.g. CoreAudio, ASIO, Windows Audio). */
    deviceType: string;
    /** Selected input device and its channels. */
    input: {
        /** Input channel names the device exposes. */
        availableChannels: string[];
        /** Name of the selected input device. */
        deviceName: string;
    };
    /** Selected output device and its channel-pair state. */
    output: {
        /** Stereo channel pair names the device exposes. */
        availableChannelPairs: string[];
        /** Name of the active channel pair. Omitted when currentChannelPairIndex is out of range. */
        currentChannelPair?: string;
        /** 0-based index of the active channel pair within availableChannelPairs; may be out of range if none is active. */
        currentChannelPairIndex: number;
        /** Name of the selected output device. */
        deviceName: string;
    };
    /** Current device properties. */
    properties: {
        /** Current buffer size in samples. */
        bufferSize: number;
        /** Current sample rate in Hz. */
        sampleRate: number;
    };
}

/** Success payload of `device list`. */
export interface DeviceListResult {
    /** Buffer sizes (samples) the current audio device supports. */
    availableBufferSizes: number[];
    /** All audio device type backends the host supports. */
    availableDeviceTypes: string[];
    /** Sample rates (Hz) the current audio device supports. */
    availableSampleRates: number[];
    /** The currently selected audio backend. */
    currentDeviceType: string;
    /** Available input devices under the current device type. */
    inputDevices: {
        /** Name of the selected input device. */
        currentDevice: string;
        /** All input device names; may be empty. */
        devices: string[];
    };
    /** MIDI input device descriptors; empty when no devices are detected. */
    midiInputDevices: {
        /** Number of MIDI channels the device supports (currently always 16). */
        availableChannels: number;
        /** Device display name as reported by the OS. */
        deviceName: string;
    }[];
    /** Available output devices under the current device type. */
    outputDevices: {
        /** Name of the selected output device. */
        currentDevice: string;
        /** All output device names; may be empty. */
        devices: string[];
    };
}

/** The `device` operations, mirroring the canonical operation tree 1:1. */
export interface DeviceOperations {
    /**
     * Read the active audio device: type, output/input device names, channel selection, sample rate, and buffer size.
     *
     * Requires the `device.read` capability.
     */
    current(options?: CallOptions): Promise<DeviceCurrentResult>;

    /**
     * List available audio devices (types, sample rates, buffer sizes) and MIDI input devices.
     *
     * Requires the `device.read` capability.
     */
    list(options?: CallOptions): Promise<DeviceListResult>;
}

